	(73, 'h6x3wiudduvy543k73r8bggv', 'INVESTIGADORES DEL TITICACA PARA EL PROGRESO ACADÉMICO Y CIENTÍFICO (INTIPAC)', '2025', 'EDUCACIÓN SECUNDARIA', 'ALANOCA GUTIERREZ REBECA', 20000.00, '2026-04-29 13:34:19.650000', '2026-04-29 13:34:19.650000', NULL, NULL, NULL, NULL, 'CIENCIAS DE LA EDUCACIÓN', 'SEGURIDAD ALIMENTARIA Y PREVENCIÓN DE LA ANEMIA INFANTIL EN COMUNIDADES AYMARAS CON ENFOQUE DE GÉNERO', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
