	(138, 'cjw8o7wsnrb05gtdskjqykte', 'GRUPO DE INVESTIGACIÓN EN PROTECCIÓN VEGETAL', '2024', 'INGENIERÍA AGRONÓMICA', 'M.Sc. Rosario Ysabel Bravo Portocarrero ', 20000.00, '2026-08-19 16:02:18.702000', '2026-08-19 16:02:18.702000', NULL, 1, 1, NULL, 'CIENCIAS AGRARIAS', 'Manejo Agronómico de cultivos.  Sub línea de Investigación: Manejo integrado de plagas y enfermedades en cultivos andinos, tropicales, forestales y pastizales', 'Dr. Israel Lima Medina\nDr. Victor Andres Gonzales Gonzales\nDoc. Contratado Ing. Juan Carlos Luna Quecaño\nDoc. Contratado Ing. Jesus Arcos Pineda\nEst. Doc. Edwin Gustavo Cañazaca Choquehuanca.\nEst. Doc. Mery Maribel Mamani Aguilar\nEst. Doc. Luis Pauro Flores\n', 'Objetivo General:\nAnalizar y sistematizar los problemas fitosanitarios que se presentan en cultivos andinos, tropicales, forestales y pastizales. \nObjetivos Específicos:\nProponer estrategias de manejo integrado por plagas, enfermedades y malezas tendientes a la disminución de los problemas fitosanitarios', 'EVALUACIÓN DE CLONES Y VARIEDADES DE PAPA RESISTENTES A PHYTOPTHORA INFESTANS Y MELOIDOGYNE HAPLA', NULL, NULL, NULL, 84.92),
