	(140, 'fvy92y2s7jjbzeyvq9oyc9pl', 'INNOVACION Y DESARROLLO EN ALIMENTACION Y NUTRICION HUMANA', '2024', 'NUTRICIÓN HUMANA', 'Dr. Wilber Paredes Ugarte', 20000.00, '2026-08-19 16:04:00.900000', '2026-08-19 16:04:00.900000', NULL, 1, 1, NULL, 'CIENCIAS DE LA SALUD', '"Alternativas y nutrición humana. Sub Linea de Investigación. Formulación de mezclas alimentarias, características físico químicas, análisis composición química, control de calidad y toxicología de los alimentos.', 'Dra. Adelaida Giovanna Viza Salas.\nDr. David Pablo Moroco Choqueña.\nDra. Luz Amanda Aguirre Flores.\nDr. Ruben Cesar Flores Ccosi.\nDra. Tania Laura Barra Quispe.\nDoc. Contratado Lic. Veronica Lizbeth Antezana Quispe\n', 'Objetivo General:\nPromover la investigación científica, tecnológica y social con proyectos que respondan a las necesidades locales, regionales y nacionales.\nObjetivos Específicos:\nContribuir a la búsqueda de alternativas de solución a las necesidades a nivel local, regional y nacional.\nFortalecer la formación profesional de los estudiantes de pre y posgrado en función de las necesidades locales, regionales y nacionales.', NULL, NULL, NULL, NULL, 83.50),
